import{_ as l,l as s,o as a,c as p,v as o,p as i,x as r,d as c,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"overlayfs","description":"","frontmatter":{"title":"overlayfs","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/overlayfs.md","filePath":"cs/overlayfs.md","lastUpdated":1789023840000}'),n={name:"cs/overlayfs.md"};function h(f,e,_,m,w,y){const t=s("Mermaid");return a(),p("div",null,[e[1]||(e[1]=o('<h1 id="overlayfs" tabindex="-1">overlayfs <a class="header-anchor" href="#overlayfs" aria-label="Permalink to &quot;overlayfs&quot;">​</a></h1><div class="epigraph"><p>联合挂载把只读 lower 与可写 upper 叠成一棵树：查找先 upper 后 lower，删除用 whiteout，拷贝上写把修改留在 upper。</p><footer>—— 据 Linux overlayfs 文档；OCI 镜像层实践对联合挂载的用法</footer></div><p><a href="/cs/fs-quota">上一课</a>收口了单层布局与记账。容器要在同一只读镜像上开许多可写视图，不能每实例拷一份 <a href="/cs/ext2-block-groups">ext4</a>。缺口是 <strong>overlayfs</strong>：VFS 里的联合挂载，不是新的盘格式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>lower 只读，upper 可写，merged 是用户看见的根。同名文件：upper 遮住 lower。删除 lower 里有的名字：upper 放 whiteout 字符设备（或 xattr 标记），查找时当作不存在。改 lower 文件：copy-up 到 upper 再改，lower 不变。缺口不是再讲 <a href="/cs/inode-dir">inode</a>，而是：两个目录树如何合成 lookup，以及 inode 号在 merged 视图里是否稳定（容器与 <code>stat</code> 的痛点）。</p><p><span class="marginnote">多层 lower 是「从左到右」的栈。workdir 是 overlay 内部 scratch，必须与 upper 同文件系统。本课不把存储驱动写成 Docker 百科。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>lookup</code>：在 upper 找，命中则停；若是 whiteout 则负缓存；否则去 lower。<code>mkdir</code>/<code>creat</code> 落在 upper。对 lower 文件第一次写：从 lower 读进 <a href="/cs/page-cache">页缓存</a>，在 upper 建文件，拷数据与部分 xattr，再切到 upper inode。目录 copy-up 只造空目录骨架，子项仍可从 lower 透出。</p>',8)),(a(),i(u,null,{default:r(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOK%5B%22lookup%22%5D%20--%3E%20U%5B%22upper%22%5D%0A%20%20U%20--%3E%7C%22whiteout%22%7C%20NEG%5B%22%E5%BD%93%E4%BD%9C%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A%20%20U%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20L%5B%22lower%22%5D%0A%20%20WRITE%5B%22%E5%86%99%20lower%20%E6%96%87%E4%BB%B6%22%5D%20--%3E%20CU%5B%22copy-up%20%E5%88%B0%20upper%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>overlay 把 <a href="/cs/fs-snapshots">快照</a> 那种「共享未改块」提升到目录树接口：共享的是 lower 文件，而不是 btrfs 结点。镜像层于是可以是 tar + overlay，而不强迫宿主机用 COW FS。不要把本课写成量化栏的分层订单簿。硬链接跨层、renames 与 whiteout 的边角是实现雷区，课序只要求机制：遮罩、白出、上写。</p><p>与配额：upper 上的分配才进可写层配额；lower 只读不记账到容器 uid，除非另做项目配额。</p><p>实现上：copy-up 会丢掉 lower 上某些 xattr 或打开的租约语义，数据库文件放 lower 再在容器里写是经典坑。inode 号在 merged 视图里可能随 copy-up 改变，stat 不稳定。 读法上只引用<a href="/cs/fs-quota">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>overlayfs</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 FUSE 版 unionfs 的全部历史。不保证 NFS 作 lower 时所有缓存语义。下一课把「文件系统不必在内核里」做成协议：FUSE。</p><p>版本字段会变，课序钉的是机制对象「overlayfs」，不是某一主线内核的结构体名。 后课默认：联合挂载用 upper/lower/whiteout/copy-up。用户态实现 VFS 操作，下一课 FUSE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>overlay 叠树：遮罩、whiteout、copy-up。</li><li>它是 VFS 联合，不是新的盘布局。</li><li>用户态文件系统协议是下一课。</li><li>出处：Linux <code>Documentation/filesystems/overlayfs.rst</code>；OCI 层实践。</li></ul>',11))])}const x=l(n,[["render",h]]);export{E as __pageData,x as default};
